import pytest

import bayes_ab


@pytest.fixture(scope="module")
def results():
    p_quad = bayes_ab.prob_b_gt_a_quad()
    p_mc_1, loss_1 = bayes_ab.prob_b_gt_a_mc()
    p_mc_2, loss_2 = bayes_ab.prob_b_gt_a_mc()
    p_grid = bayes_ab.prob_b_gt_a_grid()
    return {
        "quad": p_quad,
        "mc1": p_mc_1,
        "mc2": p_mc_2,
        "grid": p_grid,
        "loss1": loss_1,
        "loss2": loss_2,
    }


def test_pairwise_agreement_within_0p005(results):
    vals = [results["quad"], results["mc1"], results["grid"]]
    for i in range(3):
        for j in range(i + 1, 3):
            assert abs(vals[i] - vals[j]) < 0.005, (
                f"methods {i} and {j} disagree: {vals[i]} vs {vals[j]}"
            )


def test_value_in_expected_range(results):
    assert 0.97 <= results["quad"] <= 0.995
    assert 0.97 <= results["mc1"] <= 0.995


def test_expected_loss_below_threshold(results):
    assert results["loss1"] < 0.0002


def test_reproducible_across_runs(results):
    assert results["mc1"] == results["mc2"]
    assert results["loss1"] == results["loss2"]

